package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class LmdbNativeFilterEvaluationScopeTest {

	private static final long SUBJECT = 11L;
	private static final long PREDICATE = 12L;
	private static final long OBJECT = 13L;

	@Test
	void statementPatternExistsUsesCurrentEvaluationSourceAndMemo() throws Exception {
		SyntheticValueSource compileSource = compileSource(true);
		StatementPatternExistsFilter filter = new StatementPatternExistsFilter(compileSource,
				Term.constant(SUBJECT), Term.constant(PREDICATE), Term.constant(OBJECT),
				Term.constant(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID), ContextConstraint.UNRESTRICTED, false);
		SyntheticValueSource matchingEvaluation = evaluationSource(true);
		SyntheticValueSource emptyEvaluation = evaluationSource(false);
		try {
			assertThat(filter.accept(row(matchingEvaluation))).isTrue();
			assertThat(filter.accept(row(emptyEvaluation)))
					.as("a retained filter must use the current evaluation source and its own memo")
					.isFalse();
		} finally {
			matchingEvaluation.executionContext().close();
			emptyEvaluation.executionContext().close();
		}
	}

	@Test
	void existsMemoDoesNotCrossEvaluationSnapshots() throws Exception {
		PatternPlan pattern = new PatternPlan(Term.constant(SUBJECT), Term.constant(PREDICATE), Term.constant(OBJECT),
				Term.constant(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID), ContextConstraint.UNRESTRICTED, false, 1D);
		ExistsFilter filter = new ExistsFilter(pattern);
		SyntheticValueSource matchingEvaluation = evaluationSource(true);
		SyntheticValueSource emptyEvaluation = evaluationSource(false);
		try {
			assertThat(filter.accept(row(matchingEvaluation))).isTrue();
			assertThat(filter.accept(row(emptyEvaluation)))
					.as("EXISTS memoization must be isolated from the preceding evaluation snapshot")
					.isFalse();
		} finally {
			matchingEvaluation.executionContext().close();
			emptyEvaluation.executionContext().close();
		}
	}

	private static SyntheticValueSource compileSource(boolean match) throws Exception {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.has(SUBJECT, PREDICATE, OBJECT, LmdbNativeAggregateCompiler.NULL_CONTEXT_ID)).thenReturn(match);
		return new SyntheticValueSource(source, PlanValueCatalog.EMPTY);
	}

	private static SyntheticValueSource evaluationSource(boolean match) throws Exception {
		return compileSource(match).forEvaluation();
	}

	private static RowState row(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of(), null);
		layout.freeze(List.of());
		return new RowState(source, layout, EmptyBindingSet.getInstance());
	}
}
